    """Whether a Docker daemon is reachable for the testcontainers tests."""
    try:
        import docker
    except ImportError:
        return False
    try:
        client = docker.from_env()
    except Exception:
        return False
    try:
        return bool(client.ping())
    except Exception:
        return False
    finally:
        client.close()


